mapper.select:
SELECT p.*, /* 1. 상세 주소 정보 */ a1.address AS detailedAddress, a1.detail_address AS detailedAddressDetail, /* 2. 지하철 주소 정보 */ a2.address AS subwayAddress, /* 3. 대표 좌표 결정 */ CASE WHEN p.address_type_cd = 2701 THEN a1.latitude ELSE a2.latitude END AS latitude, CASE WHEN p.address_type_cd = 2701 THEN a1.longitude ELSE a2.longitude END AS longitude, /* 4. 거리 계산 */ ST_Distance_Sphere( POINT(#{userLng}, #{userLat}), POINT( CASE WHEN p.address_type_cd = 2701 THEN a1.longitude ELSE a2.longitude END, CASE WHEN p.address_type_cd = 2701 THEN a1.latitude ELSE a2.latitude END ) ) / 1000 AS distance NULL AS distance FROM TBL_PROJECT_M p LEFT JOIN TBL_ADDRESS_S a1 ON p.address_sq = a1.address_sq LEFT JOIN TBL_ADDRESS_S a2 ON p.subway_address_sq = a2.address_sq WHERE p.project_is_deleted_yn = 'N' /* [필터 1] 지역 검색 */ AND ( p.address_sq IN ( SELECT address_sq FROM TBL_ADDRESS_S WHERE area_code_sq IN ( SELECT area_code_sq FROM TBL_AREA_C WHERE parent_area_code_sq IN #{item} ) ) OR p.subway_address_sq IN ( SELECT address_sq FROM TBL_ADDRESS_S WHERE area_code_sq IN ( SELECT area_code_sq FROM TBL_AREA_C WHERE parent_area_code_sq IN #{item} ) ) ) /* [필터 2] 거리 내 검색 */
AND ST_Distance_Sphere( POINT(#{userLng}, #{userLat}), POINT( CASE WHEN p.address_type_cd = 2701 THEN a1.longitude ELSE a2.longitude END, CASE WHEN p.address_type_cd = 2701 THEN a1.latitude ELSE a2.latitude END ) ) / 1000 >= 10 AND ST_Distance_Sphere( POINT(#{userLng}, #{userLat}), POINT( CASE WHEN p.address_type_cd = 2701 THEN a1.longitude ELSE a2.longitude END, CASE WHEN p.address_type_cd = 2701 THEN a1.latitude ELSE a2.latitude END ) ) / 1000 <= #{distance}
/* [필터 3] 공통 조건 (등급, 학력, 직군) */ AND p.project_developer_grade_cd IN #{item}
AND p.project_required_education_cd IN #{item}
AND EXISTS ( SELECT 1 FROM TBL_PROJECT_RECRUIT_JOB_ROLE_S jr WHERE jr.project_sq = p.project_sq AND jr.recruit_job_position_type_cd IN #{item} ) /* [추가 필터] 단가 검색 */ AND p.project_salary >= #{minPrice} /* [필터] 기술 태그 다중 필터링 */
AND EXISTS (SELECT 1 FROM TBL_PROJECT_REQUIRED_SKILL_TAG_S rs WHERE rs.project_sq = p.project_sq AND rs.skill_tag_nm = #{tag})
/* [필터 4] 키워드 검색 - 수정됨 */
AND p.project_ttl LIKE CONCAT('%', #{searchKeyword}, '%')
AND EXISTS ( SELECT 1 FROM TBL_COMPANY_S c WHERE c.company_sq = p.company_sq AND c.company_nm LIKE CONCAT('%', #{searchKeyword}, '%') )
AND (p.project_preference_txt LIKE CONCAT('%', #{searchKeyword}, '%') OR p.project_description_txt LIKE CONCAT('%', #{searchKeyword}, '%'))
AND EXISTS ( SELECT 1 FROM TBL_PROJECT_REQUIRED_SKILL_TAG_S rs WHERE rs.project_sq = p.project_sq AND rs.skill_tag_nm LIKE CONCAT('%', #{searchKeyword}, '%') )
AND ( p.project_ttl LIKE CONCAT('%', #{searchKeyword}, '%') OR p.project_description_txt LIKE CONCAT('%', #{searchKeyword}, '%') OR p.project_preference_txt LIKE CONCAT('%', #{searchKeyword}, '%') OR EXISTS ( SELECT 1 FROM TBL_PROJECT_REQUIRED_SKILL_TAG_S rs WHERE rs.project_sq = p.project_sq AND rs.skill_tag_nm LIKE CONCAT('%', #{searchKeyword}, '%') ) OR EXISTS ( SELECT 1 FROM TBL_COMPANY_S c WHERE c.company_sq = p.company_sq AND c.company_nm LIKE CONCAT('%', #{searchKeyword}, '%') ) )
/* [필터 5] 지도 영역 검색 */ AND (CASE WHEN p.address_type_cd = 2701 THEN a1.latitude ELSE a2.latitude END BETWEEN #{minLat} AND #{maxLat}) AND (CASE WHEN p.address_type_cd = 2701 THEN a1.longitude ELSE a2.longitude END BETWEEN #{minLng} AND #{maxLng}) /* 정렬 */
ORDER BY CASE WHEN NOW() BETWEEN p.project_recruit_start_dt AND p.project_recruit_end_dt THEN 0 ELSE 1 END ASC, distance ASC ORDER BY CASE WHEN NOW() BETWEEN p.project_recruit_start_dt AND p.project_recruit_end_dt THEN 0 ELSE 1 END ASC, p.project_created_at_dtm ${sortOrder} ORDER BY CASE WHEN NOW() BETWEEN p.project_recruit_start_dt AND p.project_recruit_end_dt THEN 0 ELSE 1 END ASC, p.project_view_cnt ${sortOrder} ORDER BY CASE WHEN NOW() BETWEEN p.project_recruit_start_dt AND p.project_recruit_end_dt THEN 0 ELSE 1 END ASC, p.project_candidate_cnt ${sortOrder} ORDER BY CASE WHEN NOW() BETWEEN p.project_recruit_start_dt AND p.project_recruit_end_dt THEN 0 ELSE 1 END ASC, p.project_created_at_dtm DESC
ORDER BY CASE WHEN NOW() BETWEEN p.project_recruit_start_dt AND p.project_recruit_end_dt THEN 0 ELSE 1 END ASC, p.project_created_at_dtm DESC /* 페이징 */ LIMIT #{size} OFFSET #{offset}

SELECT /* 주소 타입(2701:상세, 2702:지하철)에 따른 시군구 결정 */ CASE WHEN p.address_type_cd = 2701 THEN a1.sigungu ELSE a2.sigungu END AS sigungu, /* 시군구별 프로젝트 수 합산 */ COUNT(p.project_sq) AS projectCount, /* 해당 시군구 프로젝트들의 평균 좌표 (핀 노출 위치) */ AVG(CASE WHEN p.address_type_cd = 2701 THEN a1.latitude ELSE a2.latitude END) AS latitude, AVG(CASE WHEN p.address_type_cd = 2701 THEN a1.longitude ELSE a2.longitude END) AS longitude FROM TBL_PROJECT_M p LEFT JOIN TBL_ADDRESS_S a1 ON p.address_sq = a1.address_sq LEFT JOIN TBL_ADDRESS_S a2 ON p.subway_address_sq = a2.address_sq WHERE p.project_is_deleted_yn = 'N' /* [필터 1] 지역 검색 */ AND ( p.address_sq IN (SELECT address_sq FROM TBL_ADDRESS_S WHERE area_code_sq IN (SELECT area_code_sq FROM TBL_AREA_C WHERE parent_area_code_sq IN #{item})) OR p.subway_address_sq IN (SELECT address_sq FROM TBL_ADDRESS_S WHERE area_code_sq IN (SELECT area_code_sq FROM TBL_AREA_C WHERE parent_area_code_sq IN #{item})) ) /* [필터 2] 거리 내 검색 */
AND ST_Distance_Sphere(POINT(#{userLng}, #{userLat}), POINT(CASE WHEN p.address_type_cd = 2701 THEN a1.longitude ELSE a2.longitude END, CASE WHEN p.address_type_cd = 2701 THEN a1.latitude ELSE a2.latitude END)) / 1000 >= 10 AND ST_Distance_Sphere(POINT(#{userLng}, #{userLat}), POINT(CASE WHEN p.address_type_cd = 2701 THEN a1.longitude ELSE a2.longitude END, CASE WHEN p.address_type_cd = 2701 THEN a1.latitude ELSE a2.latitude END)) / 1000 <= #{distance}
/* [필터 3] 공통 조건 (등급, 학력, 직군) */ AND p.project_developer_grade_cd IN #{item}
AND p.project_required_education_cd IN #{item}
AND EXISTS (SELECT 1 FROM TBL_PROJECT_RECRUIT_JOB_ROLE_S jr WHERE jr.project_sq = p.project_sq AND jr.recruit_job_position_type_cd IN #{item}) /* [필터 4] 단가 검색 */ AND p.project_salary >= #{minPrice} /* [필터] - 기술 태그 다중 필터링 */
AND EXISTS (SELECT 1 FROM TBL_PROJECT_REQUIRED_SKILL_TAG_S rs WHERE rs.project_sq = p.project_sq AND rs.skill_tag_nm = #{tag})
/* [필터 5] 키워드 검색 (제목, 작성자, 내용, 태그) */
AND p.project_ttl LIKE CONCAT('%', #{searchKeyword}, '%') AND EXISTS (SELECT 1 FROM TBL_COMPANY_S c JOIN TBL_USER_M u ON c.user_sq = u.user_sq WHERE c.company_sq = p.company_sq AND u.user_nm LIKE CONCAT('%', #{searchKeyword}, '%')) AND (p.project_preference_txt LIKE CONCAT('%', #{searchKeyword}, '%') OR p.project_description_txt LIKE CONCAT('%', #{searchKeyword}, '%')) AND EXISTS (SELECT 1 FROM TBL_PROJECT_REQUIRED_SKILL_TAG_S rs WHERE rs.project_sq = p.project_sq AND rs.skill_tag_nm LIKE CONCAT('%', #{searchKeyword}, '%')) AND ( p.project_ttl LIKE CONCAT('%', #{searchKeyword}, '%') OR p.project_description_txt LIKE CONCAT('%', #{searchKeyword}, '%') OR p.project_preference_txt LIKE CONCAT('%', #{searchKeyword}, '%') OR EXISTS (SELECT 1 FROM TBL_PROJECT_REQUIRED_SKILL_TAG_S rs WHERE rs.project_sq = p.project_sq AND rs.skill_tag_nm LIKE CONCAT('%', #{searchKeyword}, '%')) )
/* [필터 6] 지도 영역(Bounds) 내 검색 */ AND ( CASE WHEN p.address_type_cd = 2701 THEN a1.latitude ELSE a2.latitude END BETWEEN #{minLat} AND #{maxLat} ) AND ( CASE WHEN p.address_type_cd = 2701 THEN a1.longitude ELSE a2.longitude END BETWEEN #{minLng} AND #{maxLng} ) /* 시군구 기준으로 그룹화 */ GROUP BY sigungu

SELECT COUNT(*) FROM TBL_PROJECT_M p WHERE p.project_is_deleted_yn = 'N' /* [필터 1] 지역 검색 */ AND p.address_sq IN ( SELECT address_sq FROM TBL_ADDRESS_S WHERE area_code_sq IN ( SELECT area_code_sq FROM TBL_AREA_C WHERE parent_area_code_sq IN #{item} ) ) /* [필터 2] 공통 조건 (등급, 학력, 직군) */ AND p.project_developer_grade_cd IN #{item}
AND p.project_required_education_cd IN #{item}
AND EXISTS ( SELECT 1 FROM TBL_PROJECT_RECRUIT_JOB_ROLE_S jr WHERE jr.project_sq = p.project_sq AND jr.recruit_job_position_type_cd IN #{item} ) /* [추가 필터] 단가 검색 */ AND p.project_salary >= #{minPrice} /* [필터] - 기술 태그 다중 필터링 */
AND EXISTS (SELECT 1 FROM TBL_PROJECT_REQUIRED_SKILL_TAG_S rs WHERE rs.project_sq = p.project_sq AND rs.skill_tag_nm = #{tag})
/* [필터 3] 키워드 검색 */
AND p.project_ttl LIKE CONCAT('%', #{searchKeyword}, '%') AND EXISTS ( SELECT * FROM TBL_COMPANY_S c JOIN TBL_USER_M u ON c.user_sq = u.user_sq WHERE c.company_sq = p.company_sq AND u.user_nm LIKE CONCAT('%', #{searchKeyword}, '%') ) AND ( p.project_preference_txt LIKE CONCAT('%', #{searchKeyword}, '%') OR p.project_description_txt LIKE CONCAT('%', #{searchKeyword}, '%') ) AND EXISTS ( SELECT 1 FROM TBL_PROJECT_REQUIRED_SKILL_TAG_S rs WHERE rs.project_sq = p.project_sq AND rs.skill_tag_nm LIKE CONCAT('%', #{searchKeyword}, '%') ) AND ( p.project_ttl LIKE CONCAT('%', #{searchKeyword}, '%') OR p.project_description_txt LIKE CONCAT('%', #{searchKeyword}, '%') OR p.project_preference_txt LIKE CONCAT('%', #{searchKeyword}, '%') OR EXISTS ( SELECT 1 FROM TBL_PROJECT_REQUIRED_SKILL_TAG_S rs WHERE rs.project_sq = p.project_sq AND rs.skill_tag_nm LIKE CONCAT('%', #{searchKeyword}, '%') ) )

 SELECT
		c.common_code_nm FROM TBL_PROJECT_CONTRACT_TYPE_S m JOIN TBL_COMMON_CODE_C c ON
		m.contract_type_cd = c.common_code_sq WHERE m.project_sq = #{projectSq}

 SELECT
		c.common_code_nm FROM TBL_PROJECT_RECRUIT_JOB_ROLE_S m JOIN TBL_COMMON_CODE_C c ON
		m.recruit_job_position_type_cd = c.common_code_sq WHERE m.project_sq = #{projectSq}

 SELECT
		MIN(interview_available_dtm) AS minTime, MAX(interview_available_dtm) AS maxTime FROM
		TBL_PROJECT_INTERVIEW_TIME_SLOT_S WHERE project_sq = #{projectSq}

 SELECT
		project_application_member_type_cd FROM tbl_project_application_h WHERE
		project_application_sq = #{applicationSq}
